class LRUCache:
    def __init__(self, capacity: int):
        if not isinstance(capacity, int):
            raise TypeError("capacity must be an integer")
        if capacity < 1:
            raise ValueError("capacity must be at least 1")

        self._capacity = capacity
        self._cache = {}  # Maps key to value
        self._order = []  # List of keys in order of usage (LRU at index 0, MRU at end)

    def _move_to_end(self, key: str):
        """Move a key to the end of the order list (mark as most recently used)."""
        if key in self._order:
            self._order.remove(key)
        self._order.append(key)

    def get(self, key, default=None):
        if key not in self._cache:
            return default
        self._move_to_end(key)
        return self._cache[key]

    def put(self, key: str, value):
        if key in self._cache:
            self._cache[key] = value
            self._move_to_end(key)
        else:
            if len(self._order) >= self._capacity:
                # Remove the least recently used key (first in the list)
                lru_key = self._order.pop(0)
                del self._cache[lru_key]

            self._cache[key] = value
            self._order.append(key)

    def __len__(self):
        return len(self._cache)

    def __contains__(self, key):
        return key in self._cache

    def keys(self):
        return list(self._order)
