function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();

    if (trimmed === '') {
      throw new SyntaxError('malformed part: empty part');
    }

    if (trimmed.includes('--')) {
      throw new SyntaxError('malformed part: more than one dash');
    }

    const dashIndex = trimmed.indexOf('-');

    if (dashIndex === -1) {
      // Single number
      if (trimmed === '' || trimmed === '-') {
        throw new SyntaxError('malformed part: missing number');
      }
      const num = Number(trimmed);
      if (Number.isNaN(num) || !Number.isInteger(num) || num < 0) {
        throw new SyntaxError('malformed part: invalid number');
      }
      result.add(num);
    } else if (dashIndex === 0 || dashIndex === trimmed.length - 1) {
      // Leading or trailing dash
      throw new SyntaxError('malformed part: missing start or end');
    } else if (trimmed.indexOf('-', dashIndex + 1) !== -1) {
      // More than one dash
      throw new SyntaxError('malformed part: more than one dash');
    } else {
      // Range: lo-hi
      const loStr = trimmed.slice(0, dashIndex);
      const hiStr = trimmed.slice(dashIndex + 1);

      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('malformed part: missing start or end');
      }

      const lo = Number(loStr);
      const hi = Number(hiStr);

      if (Number.isNaN(lo) || Number.isNaN(hi)) {
        throw new SyntaxError('malformed part: invalid number');
      }

      if (!Number.isInteger(lo) || !Number.isInteger(hi)) {
        throw new SyntaxError('malformed part: non-integer number');
      }

      if (lo < 0 || hi < 0) {
        throw new SyntaxError('malformed part: negative number');
      }

      if (lo > hi) {
        throw new RangeError('range start is greater than end');
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

