def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    result = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Start of a quoted field
            j = i + 1
            while j < n:
                if line[j] == '"':
                    # Check for doubled quote
                    if j + 1 < n and line[j + 1] == '"':
                        j += 2
                    else:
                        # End of quoted field
                        break
                else:
                    j += 1
            else:
                # No closing quote found
                raise ValueError("Unclosed quoted field")

            # j is now at the closing quote
            # Extract the field content, handling doubled quotes
            field_chars = []
            k = i + 1
            while k < j:
                if line[k] == '"':
                    # Check if next char is also a quote
                    if k + 1 < j and line[k + 1] == '"':
                        field_chars.append('"')
                        k += 2
                    else:
                        # This shouldn't happen if logic is correct, but safety
                        field_chars.append('"')
                        k += 1
                else:
                    field_chars.append(line[k])
                    k += 1

            result.append("".join(field_chars))

            # After closing quote, must be comma or end of line
            if j + 1 < n:
                if line[j + 1] != ',':
                    raise ValueError("Invalid character after quoted field")
                i = j + 2
            else:
                i = j + 1
        else:
            # Unquoted field
            comma_pos = line.find(',', i)
            if comma_pos == -1:
                # No more commas, take rest of line
                result.append(line[i:])
                break
            else:
                result.append(line[i:comma_pos])
                i = comma_pos + 1

    return result
