        # Check for zero count
        if count == 0:
            raise ValueError("Count must be at least 1")

        # Check if there's a character after the count
        if j >= len(s):
            raise ValueError("Missing character after count")

        # Check if the character is a digit (should not be)
        if s[j].isdigit():
            raise ValueError("Character after count must not be a digit")

        # Append the character repeated count times
        result.append(s[j] * count)
        i = j + 1

    return "".join(result)
