function createLimiter({ capacity, refillPerSec, now }) {
  if (typeof capacity !== 'number' || !Number.isInteger(capacity) || capacity <= 0) {
    throw new RangeError('capacity must be a positive integer');
  }
  if (typeof refillPerSec !== 'number' || !Number.isFinite(refillPerSec) || refillPerSec <= 0) {
    throw new RangeError('refillPerSec must be a positive finite number');
  }
  if (typeof now !== 'function') {
    throw new TypeError('now must be a function');
  }

  let tokens = capacity;
  let lastRefillTime = now();

  function tryTake(n = 1) {
    if (typeof n !== 'number' || !Number.isInteger(n) || n <= 0) {
      throw new RangeError('n must be a positive integer');
    }
    if (n > capacity) {
      return false;
    }

    const currentTime = now();
    const elapsedSec = (currentTime - lastRefillTime) / 1000;
    if (elapsedSec > 0) {
      tokens = Math.min(capacity, tokens + refillPerSec * elapsedSec);
      lastRefillTime = currentTime;
    }

    if (tokens >= n) {
      tokens -= n;
      return true;
    }
    return false;
  }

  return { tryTake };
}

