def add_months(date_str: str, n: int) -> str:
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")

    try:
        parts = date_str.split('-')
        if len(parts) != 3:
            raise ValueError("Invalid date format")
        year = int(parts[0])
        month = int(parts[1])
        day = int(parts[2])
    except ValueError:
        raise ValueError("Invalid date format")

    if not (1 <= year <= 9999):
        raise ValueError("Year must be between 1 and 9999")

    try:
        original_date = date(year, month, day)
    except ValueError:
        raise ValueError("Invalid date")

    # Calculate new year and month
    new_month = month + n
    new_year = year

    # Adjust for overflow/underflow of months
    if new_month > 12:
        years_to_add = (new_month - 1) // 12
        new_month = ((new_month - 1) % 12) + 1
        new_year += years_to_add
    elif new_month <= 0:
        years_to_add = (-new_month + 11) // 12
        new_month = 12 - ((-new_month + 11) % 12)
        new_year -= years_to_add

    if not (1 <= new_year <= 9999):
        raise ValueError("Resulting year must be between 1 and 9999")

    # Determine the maximum day for the target month
    if new_month in [1, 3, 5, 7, 8, 10, 12]:
        max_days = 31
    elif new_month in [4, 6, 9, 11]:
        max_days = 30
    else:  # February
        max_days = 29 if isleap(new_year) else 28

    # Clamp day to the maximum allowed for the target month
    if day > max_days:
        day = max_days

    try:
        result_date = date(new_year, new_month, day)
    except ValueError:
        raise ValueError("Invalid date")

    return result_date.isoformat()
