def validate_username(name):
    if not isinstance(name, str):
        raise TypeError("name must be a string")

    # Normalize: strip whitespace and convert to lowercase
    normalized = name.strip().lower()

    # Check length
    if not (3 <= len(normalized) <= 20):
        raise ValueError("Username length must be between 3 and 20 characters")

    # Check allowed characters: a-z, 0-9, _, .
    allowed_chars = set("abcdefghijklmnopqrstuvwxyz0123456789_.")
    if not all(c in allowed_chars for c in normalized):
        raise ValueError("Username contains invalid characters")

    # Check starts with a letter a-z
    if not normalized[0].isalpha():
        raise ValueError("Username must start with a letter")

    # Check does not end with _ or .
    if normalized[-1] in "_.":
        raise ValueError("Username cannot end with '_' or '.'")

    # Check for consecutive special characters (_ or .)
    for i in range(len(normalized) - 1):
        if normalized[i] in "_." and normalized[i + 1] in "_.":
            raise ValueError("Username cannot contain consecutive special characters")

    return normalized
