from collections import deque

def maze_steps(grid):
    if not grid:
        raise ValueError("Grid must not be empty")

    row_len = len(grid[0])
    for row in grid:
        if len(row) != row_len:
            raise ValueError("All rows must have the same length")
        for char in row:
            if char not in 'SE#.':
                raise ValueError(f"Invalid character '{char}' found in grid")

    start = None
    end = None

    for r, row in enumerate(grid):
        for c, char in enumerate(row):
            if char == 'S':
                if start is not None:
                    raise ValueError("There must be exactly one start position 'S'")
                start = (r, c)
            elif char == 'E':
                if end is not None:
                    raise ValueError("There must be exactly one exit position 'E'")
                end = (r, c)

    if start is None:
        raise ValueError("There must be exactly one start position 'S'")
    if end is None:
        raise ValueError("There must be exactly one exit position 'E'")

    queue = deque([(start, 0)])
    visited = {start}

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        (r, c), steps = queue.popleft()

        if (r, c) == end:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if (nr, nc) not in visited:
                    cell = grid[nr][nc]
                    if cell in 'SE.':
                        visited.add((nr, nc))
                        queue.append(((nr, nc), steps + 1))

    return -1
